#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_RANGE 255
#define PWM_FREQ 1000
#define STEP 10

static volatile sig_atomic_t running = 1;

static void sigint_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    int rc;

    /* Install SIGINT handler for clean shutdown */
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "pigpio initialisation failed (code %d).\n", rc);
        fprintf(stderr, "Check that pigpiod is not running and you have root privileges.\n");
        return EXIT_FAILURE;
    }

    /* Configure PWM on GPIO 18 */
    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) != PWM_FREQ) {
        fprintf(stderr, "Warning: could not set PWM frequency to %d Hz on GPIO %d.\n",
                PWM_FREQ, PWM_PIN);
    }

    /* Main loop: alternate duty cycle */
    while (running) {
        for (int duty = 0; duty <= PWM_RANGE && running; duty += STEP) {
            if (gpioPWM(PWM_PIN, duty) != 0) {
                fprintf(stderr, "Failed to set PWM duty cycle %d on GPIO %d.\n",
                        duty, PWM_PIN);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            printf("PWM duty cycle: %d\n", duty);
            fflush(stdout);
            gpioDelay(500000); /* 0.5 s */
        }

        for (int duty = PWM_RANGE; duty >= 0 && running; duty -= STEP) {
            if (gpioPWM(PWM_PIN, duty) != 0) {
                fprintf(stderr, "Failed to set PWM duty cycle %d on GPIO %d.\n",
                        duty, PWM_PIN);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            printf("PWM duty cycle: %d\n", duty);
            fflush(stdout);
            gpioDelay(500000); /* 0.5 s */
        }
    }

    /* Clean shutdown: turn off PWM and release pigpio */
    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    printf("\nProgram terminated cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    27
#define CONSUMER    "hcsr04"

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static long elapsed_us(const struct timespec *start, const struct timespec *end) {
    long s = (long)(end->tv_sec - start->tv_sec);
    long ns = (long)(end->tv_nsec - start->tv_nsec);
    return s * 1000000L + ns / 1000L;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trig) {
        perror("gpiod_chip_get_line(trigger)");
        goto cleanup;
    }
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        perror("gpiod_chip_get_line(echo)");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(trigger)");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, CONSUMER) < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }

    while (running) {
        struct timespec t0, t1;
        long pulse_us;

        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value(trig low)");
            break;
        }
        usleep(2);
        if (gpiod_line_set_value(trig, 1) < 0) {
            perror("gpiod_line_set_value(trig high)");
            break;
        }
        usleep(10);
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value(trig low)");
            break;
        }

        if (clock_gettime(CLOCK_MONOTONIC, &t0) == -1) {
            perror("clock_gettime");
            break;
        }

        while (gpiod_line_get_value(echo) == 0) {
            if (!running) goto cleanup;
            if (clock_gettime(CLOCK_MONOTONIC, &t1) == -1) {
                perror("clock_gettime");
                goto cleanup;
            }
            if (elapsed_us(&t0, &t1) > 100000L) {
                fprintf(stderr, "Timeout waiting for echo high.\n");
                goto cleanup;
            }
        }

        if (clock_gettime(CLOCK_MONOTONIC, &t0) == -1) {
            perror("clock_gettime");
            break;
        }

        while (gpiod_line_get_value(echo) == 1) {
            if (!running) goto cleanup;
            if (clock_gettime(CLOCK_MONOTONIC, &t1) == -1) {
                perror("clock_gettime");
                goto cleanup;
            }
            if (elapsed_us(&t0, &t1) > 230000L) {
                fprintf(stderr, "Timeout waiting for echo low.\n");
                goto cleanup;
            }
        }

        if (clock_gettime(CLOCK_MONOTONIC, &t1) == -1) {
            perror("clock_gettime");
            break;
        }

        pulse_us = elapsed_us(&t0, &t1);

        if (pulse_us < 0 || pulse_us > 4000000L) {
            fprintf(stderr, "Pulse out of range: %ld us\n", pulse_us);
            goto cleanup;
        }

        float distance = (float)pulse_us / 58.0f;
        printf("Distance: %.2f cm\n", distance);
        fflush(stdout);

        for (int i = 0; i < 60 && running; i++) {
            sleep(1);
        }
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return rc;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x28

/* ADS1115 register addresses */
#define ADS1115_REG_CONVERSION  0x00
#define ADS1115_REG_CONFIG      0x01

/* Config register bits */
#define ADS1115_CFG_OS_BEGIN    0x8000  /* Begin single conversion */
#define ADS1115_CFG_MUX_AIN0   0x4000  /* AIN0 vs GND */
#define ADS1115_CFG_PGA_4_096V 0x0200  /* +/-4.096 V range */
#define ADS1115_CFG_MODE_SING  0x0100  /* Single-shot mode */
#define ADS1115_CFG_DR_128SPS  0x0080  /* 128 SPS */

#define SAMPLE_INTERVAL_SEC    5
#define CONVERSION_WAIT_MS     10     /* 128 SPS needs ~7.8 ms; 10 ms is safe */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit value to an ADS1115 register (MSB first). */
static int ads1115_write_reg(int fd, uint8_t reg, uint16_t value)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(value >> 8);
    buf[2] = (uint8_t)(value & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "write(reg 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit value from an ADS1115 register (MSB first). */
static int ads1115_read_reg(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "write(reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }

    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "read(reg 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* Trigger a single-shot conversion on AIN0 and read the result. */
static int ads1115_read_ain0(int fd, int16_t *value)
{
    uint16_t config = ADS1115_CFG_OS_BEGIN | ADS1115_CFG_MUX_AIN0 |
                      ADS1115_CFG_PGA_4_096V | ADS1115_CFG_MODE_SING |
                      ADS1115_CFG_DR_128SPS;

    if (ads1115_write_reg(fd, ADS1115_REG_CONFIG, config) != 0)
        return -1;

    /* Wait for conversion to complete (~7.8 ms at 128 SPS). */
    usleep(CONVERSION_WAIT_MS * 1000);

    uint16_t raw;
    if (ads1115_read_reg(fd, ADS1115_REG_CONVERSION, &raw) != 0)
        return -1;

    *value = (int16_t)raw;
    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    /* Install SIGINT handler for clean shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus. */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the ADS1115 device. */
    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                ADS1115_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Verify the device is present by reading the config register. */
    uint16_t cfg_check;
    if (ads1115_read_reg(fd, ADS1115_REG_CONFIG, &cfg_check) != 0) {
        fprintf(stderr, "ADS1115 not responding at 0x%02X\n", ADS1115_ADDR);
        goto cleanup;
    }

    printf("ADS1115 at 0x%02X verified (config=0x%04X). Sampling AIN0 every %d s.\n",
           ADS1115_ADDR, cfg_check, SAMPLE_INTERVAL_SEC);

    while (g_running) {
        int16_t raw;
        if (ads1115_read_ain0(fd, &raw) != 0) {
            fprintf(stderr, "ADS1115 read failed; continuing.\n");
        } else {
            /*
             * Validate the 16-bit signed result against the PGA full-scale
             * for the configured range (+/-4.096 V).  At 16-bit resolution
             * the full-scale code is 0x7FFF (32767) for positive,
             * -32768 for negative.
             */
            if (raw > 32767 || raw < -32768) {
                fprintf(stderr, "Warning: reading out of range (%d).\n", raw);
            }
            printf("AIN0: %d\n", raw);
            fflush(stdout);
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly. */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC * 10 && g_running; i++)
            usleep(100 * 1000);
    }

    printf("\nExiting cleanly.\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0)
        close(fd);
    return rc;
}

