            goto cleanup;
        }
        printf("Cycle %d: GPIO %d HIGH\n", i + 1, GPIO_LINE);
        fflush(stdout);
        sleep(DELAY_SEC);

        if (!running) break;

        if (gpiod_line_set_value(line, 0) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
