    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00

static volatile int keep_running = 1;

void handle_sigint(int sig) {
    (void)sig;
    keep_running = 0;
}

int main() {
    int fd;
    uint8_t config[3];
    uint8_t reg;
    uint8_t buf[2];
    int16_t raw;

    signal(SIGINT, handle_sigint);

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open /dev/i2c-1");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    // Config: AIN0 single-ended, +/-4.096V, 128 SPS, continuous
    config[0] = CONFIG_REG;
    config[1] = 0xC0; // MUX[14:12] = 100 (AIN0 vs GND)
    config[2] = 0x83; // PGA[11:9] = 001 (+/-4.096V)
    config[3] = 0x40; // Mode[8] = 0 (continuous), DR[7:5] = 100 (128 SPS)
    config[4] = 0x00; // Comparator disabled

    if (write(fd, config, 5) != 5) {
        perror("Failed to write config to ADS1115");
        close(fd);
        return 1;
    }

    // Wait for first conversion (128 SPS -> ~8ms per conversion)
    usleep(10000);

    while (keep_running) {
        reg = CONVERSION_REG;
        if (write(fd, &reg, 1) != 1) {
            perror("Failed to set conversion register");
            break;
        }
        if (read(fd, buf, 2) != 2) {
            perror("Failed to read conversion data");
            break;
        }
        raw = (int16_t)((buf[0] << 8) | buf[1]);
        printf("ADC Value: %d\n", raw);
        usleep(10000);
    }

    close(fd);
    return 0;
}

