#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define CONSUMER    "hcsr04"

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static long elapsed_us(const struct timespec *start, const struct timespec *end) {
    long s = (long)(end->tv_sec - start->tv_sec);
    long ns = (long)(end->tv_nsec - start->tv_nsec);
    return s * 1000000L + ns / 1000L;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trig) {
        perror("gpiod_chip_get_line(trigger)");
        goto cleanup;
    }
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        perror("gpiod_chip_get_line(echo)");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(trigger)");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, CONSUMER) < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }

    while (running) {
        struct timespec t0, t1;
        long pulse_us;

        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value(trig low)");
            break;
        }
        usleep(2);
        if (gpiod_line_set_value(trig, 1) < 0) {
            perror("gpiod_line_set_value(trig high)");
            break;
        }
        usleep(10);
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value(trig low)");
            break;
        }

        if (clock_gettime(CLOCK_MONOTONIC, &t0) == -1) {
            perror("clock_gettime");
            break;
        }

        while (gpiod_line_get_value(echo) == 0) {
            if (!running) goto cleanup;
            if (clock_gettime(CLOCK_MONOTONIC, &t1) == -1) {
                perror("clock_gettime");
                goto cleanup;
            }
            if (elapsed_us(&t0, &t1) > 100000L) {
                fprintf(stderr, "Timeout waiting for echo high.\n");
                goto cleanup;
            }
        }

        if (clock_gettime(CLOCK_MONOTONIC, &t0) == -1) {
            perror("clock_gettime");
            break;
        }

        while (gpiod_line_get_value(echo) == 1) {
            if (!running) goto cleanup;
            if (clock_gettime(CLOCK_MONOTONIC, &t1) == -1) {
                perror("clock_gettime");
                goto cleanup;
            }
            if (elapsed_us(&t0, &t1) > 200000L) {
                fprintf(stderr, "Timeout waiting for echo low.\n");
                goto cleanup;
            }
        }

        if (clock_gettime(CLOCK_MONOTONIC, &t1) == -1) {
            perror("clock_gettime");
            break;
        }

        pulse_us = elapsed_us(&t0, &t1);

        if (pulse_us < 0 || pulse_us > 4000000L) {
            fprintf(stderr, "Pulse out of range: %ld us\n", pulse_us);
            goto cleanup;
        }

        float distance = (float)pulse_us / 58.0f;
        printf("Distance: %.2f cm\n", distance);
        fflush(stdout);

        sleep(1);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return rc;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 4
#define PERIOD_US 50000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request the line as output, initial value LOW */
    if (gpiod_line_request_output(line, "blink", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    /* Main blink loop */
    while (running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }

        val = !val;
        if (gpiod_line_set_value(line, val) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }

        printf("GPIO %d set to %d\n", GPIO_LINE, val);
        fflush(stdout);

        usleep(PERIOD_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure the line is released even on error paths */
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <signal.h>

static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int signo) {
    (void)signo;
    g_stop = 1;
}

static int install_handler(int signo) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    return sigaction(signo, &sa, NULL);
}

int main(void) {
    int fd = -1;
    char buf[256];
    ssize_t n;

    if (install_handler(SIGINT) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (install_handler(SIGTERM) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    fd = open("/dev/ttyAMA0", O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        perror("open(\"/dev/ttyAMA0\")");
        return EXIT_FAILURE;
    }

    /* Clear O_NDELAY so reads block. */
    if (fcntl(fd, F_SETFL, 0) < 0) {
        perror("fcntl(F_SETFL)");
        close(fd);
        return EXIT_FAILURE;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr");
        close(fd);
        return EXIT_FAILURE;
    }

    cfsetispeed(&tty, B9600);
    cfsetospeed(&tty, B9600);

    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_cflag &= ~CRTSCTS;
    tty.c_cflag |= CREAD | CLOCAL;

    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);
    tty.c_oflag &= ~OPOST;

    tty.c_cc[VMIN] = 1;
    tty.c_cc[VTIME] = 10; /* 1 s inter-byte timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        close(fd);
        return EXIT_FAILURE;
    }
    tcflush(fd, TCIOFLUSH);

    printf("Serial port initialized on /dev/ttyAMA0 at 9600 baud.\n");
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (!g_stop) {
        n = read(fd, buf, sizeof(buf) - 1);
        if (n < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("read");
            break;
        }
        if (n == 0) {
            /* Timeout — no data within VTIME. */
            continue;
        }
        buf[n] = '\0';
        printf("Received: %s", buf);
        fflush(stdout);
    }

    if (fd >= 0) {
        close(fd);
    }
    printf("\nSerial port closed. Exiting.\n");
    return EXIT_SUCCESS;
}

