#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define DHT11_PIN 4
#define MAX_TIMINGS 85
#define DHT11_TIMEOUT_US 200

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static int wait_for_level(struct gpiod_line *line, int target, int timeout_us) {
    int elapsed = 0;
    while (elapsed < timeout_us) {
        if (gpiod_line_get_value(line) == target) return 0;
        usleep(1);
        elapsed++;
    }
    return -1;
}

static int read_dht11(struct gpiod_line *line, float *humidity, float *temperature) {
    uint8_t data[5] = {0, 0, 0, 0, 0};
    int i, j = 0;

    if (gpiod_line_request_output(line, "dht11", 1) < 0) return -1;
    usleep(500);
    gpiod_line_set_value(line, 0);
    usleep(20000);
    gpiod_line_set_value(line, 1);
    usleep(40);
    if (gpiod_line_request_input(line, "dht11") < 0) return -1;

    if (wait_for_level(line, 0, DHT11_TIMEOUT_US) < 0) return -2;
    if (wait_for_level(line, 1, DHT11_TIMEOUT_US) < 0) return -2;
    if (wait_for_level(line, 0, DHT11_TIMEOUT_US) < 0) return -2;

    for (i = 0; i < MAX_TIMINGS; i++) {
        int count = 0;
        while (gpiod_line_get_value(line) == 0) {
            if (++count > 255) return -2;
            usleep(1);
        }
        count = 0;
        while (gpiod_line_get_value(line) == 1) {
            if (++count > 255) return -2;
            usleep(1);
        }
        data[j / 8] <<= 1;
        if (count > 16) data[j / 8] |= 1;
        j++;
        if (j == 40) break;
    }

    if (j < 40) return -2;
    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) return -3;

    *humidity = (float)((data[0] << 8) | data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) | data[3]) / 10.0;
    if (data[2] & 0x80) *temperature = -*temperature;

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    float humidity, temperature;
    int rc = 1;

    struct sigaction sa = {0};
    sa.sa_handler = sighandler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    line = gpiod_chip_get_line(chip, DHT11_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    int ret = read_dht11(line, &humidity, &temperature);
    if (ret == 0) {
        printf("Humidity: %.1f%%, Temperature: %.1fC\n", humidity, temperature);
        rc = 0;
    } else if (ret == -2) {
        fprintf(stderr, "DHT11: No response (sensor absent or wiring fault)\n");
    } else if (ret == -3) {
        fprintf(stderr, "DHT11: Checksum error\n");
    } else {
        fprintf(stderr, "DHT11: Read error (code %d)\n", ret);
    }

cleanup:
    if (line) gpiod_line_release(line);
    if (chip) gpiod_chip_close(chip);
    return rc;
}

