#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 2
#define PWM_PIN_2 3
#define PWM_PIN_3 18
#define PWM_RANGE 100
#define PWM_FREQ 1000
#define STEP_DELAY_US 150000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (is the pigpio daemon running?)\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: could not install SIGTERM handler\n");
    }

    if (gpioSetMode(PWM_PIN_1, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", PWM_PIN_1);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN_2, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", PWM_PIN_2);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN_3, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", PWM_PIN_3);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN_1, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d\n", PWM_PIN_1);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(PWM_PIN_2, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d\n", PWM_PIN_2);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(PWM_PIN_3, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d\n", PWM_PIN_3);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d\n", PWM_PIN_1);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d\n", PWM_PIN_2);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d\n", PWM_PIN_3);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int duty_cycle = 0;
    int direction = 1;

    while (running) {
        if (gpioPWM(PWM_PIN_1, duty_cycle) != 0) {
            fprintf(stderr, "Error: failed to set PWM on GPIO %d\n", PWM_PIN_1);
            break;
        }
        if (gpioPWM(PWM_PIN_2, duty_cycle) != 0) {
            fprintf(stderr, "Error: failed to set PWM on GPIO %d\n", PWM_PIN_2);
            break;
        }
        if (gpioPWM(PWM_PIN_3, duty_cycle) != 0) {
            fprintf(stderr, "Error: failed to set PWM on GPIO %d\n", PWM_PIN_3);
            break;
        }

        printf("PWM on GPIO %d: %d, GPIO %d: %d, GPIO %d: %d\n",
               PWM_PIN_1, duty_cycle, PWM_PIN_2, duty_cycle, PWM_PIN_3, duty_cycle);
        fflush(stdout);

        duty_cycle += direction;
        if (duty_cycle >= PWM_RANGE) {
            duty_cycle = PWM_RANGE - 1;
            direction = -1;
        } else if (duty_cycle <= 0) {
            duty_cycle = 1;
            direction = 1;
        }

        usleep(STEP_DELAY_US);
    }

    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

