#include <linux/i2c-dev.h>
#include <signal.h>

#define OPT3001_ADDR 0x44
#define I2C_DEV "/dev/i2c-1"

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) return -1;
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        perror("open " I2C_DEV);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, OPT3001_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return EXIT_FAILURE;
    }

    uint16_t result;
    if (i2c_read_reg16(fd, 0x00, &result) < 0) {
        fprintf(stderr, "Failed to read OPT3001\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("OPT3001 Reading: 0x%04X\n", result);

    close(fd);
    return EXIT_SUCCESS;
}

