    /* Request the line as output, initial value LOW */
    ret = gpiod_line_request_output(line, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Main blink loop */
    while (running) {
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value(1)");
            break;
        }
        printf("GPIO %d HIGH\n", GPIO_LINE);
        fflush(stdout);
        sleep(1);

        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value(0)");
            break;
        }
        printf("GPIO %d LOW\n", GPIO_LINE);
        fflush(stdout);
        sleep(1);
    }

    /* Clean up: ensure LOW and release resources */
    gpiod_line_set_value(line, 0);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

