#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 2
#define CYCLES 3
#define DELAY_MS 100

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "blink", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    for (int i = 0; i < CYCLES && running; i++) {
        if (gpiod_line_set_value(line, 1) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }
        printf("GPIO %d: HIGH\n", GPIO_LINE);
        fflush(stdout);
        usleep(DELAY_MS * 1000);
        if (!running) break;

        if (gpiod_line_set_value(line, 0) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }
        printf("GPIO %d: LOW\n", GPIO_LINE);
        fflush(stdout);
        usleep(DELAY_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 4
#define PWM_PIN_2 12
#define PWM_PIN_3 18

static volatile int keep_running = 1;

void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);

    while (keep_running) {
        int duty1 = 128;
        int duty2 = 255;
        int duty3 = 0;

        gpioPWM(PWM_PIN_1, duty1);
        gpioPWM(PWM_PIN_2, duty2);
        gpioPWM(PWM_PIN_3, duty3);

        printf("PWM1=%d, PWM2=%d, PWM3=%d\n", duty1, duty2, duty3);
        fflush(stdout);

        gpioDelay(1000000);
    }

    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

