#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 18
#define PWM_PIN_3 27

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGTERM handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3};
    int num_pins = sizeof(pins) / sizeof(pins[0]);

    for (int i = 0; i < num_pins; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    while (running) {
        for (int i = 0; i < num_pins; i++) {
            int duty = (i + 1) * 10000; /* 0, 10000, 20000 */
            if (gpioPWM(pins[i], duty) != 0) {
                fprintf(stderr, "Failed to set PWM on GPIO %d\n", pins[i]);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            printf("GPIO %d: %d\n", pins[i], duty);
        }
        sleep(5);
    }

    /* Clean shutdown: turn off all PWM outputs */
    for (int i = 0; i < num_pins; i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define NUM_SENSORS 3
static const int sensor_pins[NUM_SENSORS] = {4, 17, 18};

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(int pin, float *temp) {
    char path[64];
    char line[256];
    FILE *fp;

    snprintf(path, sizeof(path), "/sys/bus/w1/devices/28-%012llX/w1_slave", (unsigned long long)pin);

    fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }

    if (!fgets(line, sizeof(line), fp)) {
        fprintf(stderr, "Error reading from %s: %s\n", path, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    if (strstr(line, "YES") == NULL) {
        fprintf(stderr, "CRC check failed for pin %d\n", pin);
        return -1;
    }

    char *t = strstr(line, "t=");
    if (!t) {
        fprintf(stderr, "Temperature token not found for pin %d\n", pin);
        return -1;
    }

    long raw = strtol(t + 2, NULL, 10);
    *temp = (float)raw / 1000.0f;

    if (*temp < -55.0f || *temp > 125.0f) {
        fprintf(stderr, "Temperature out of range for pin %d: %.2f\n", pin, *temp);
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    while (running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            float temp;
            if (read_temperature(sensor_pins[i], &temp) == 0) {
                printf("Pin %d: %.2f C\n", sensor_pins[i], temp);
            } else {
                fprintf(stderr, "Failed to read temperature from pin %d\n", sensor_pins[i]);
            }
        }
        printf("---\n");
        fflush(stdout);

        if (running) {
            sleep(5);
        }
    }

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define HTU21D_ADDR 0x40
#define I2C_DEV "/dev/i2c-1"

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_measurement(int fd, float *temperature, float *humidity) {
    uint8_t data[3];

    if (i2c_write_cmd(fd, 0xE3) < 0) return -1;
    usleep(50000);
    if (i2c_read_bytes(fd, data, 3) < 0) return -1;

    uint16_t raw_temp = ((uint16_t)data[0] << 8) | data[1];
    uint16_t raw_hum  = ((uint16_t)data[2] << 8) | data[3];

    *temperature = -46.85 + 175.72 * (float)raw_temp / 65536.0;
    *humidity    = -6.0 + 125.0 * (float)raw_hum / 65536.0;

    if (*temperature < -40.0 || *temperature > 125.0) {
        fprintf(stderr, "Temperature out of range: %.2f C\n", *temperature);
        return -1;
    }
    if (*humidity < 0.0 || *humidity > 100.0) {
        fprintf(stderr, "Humidity out of range: %.2f %%\n", *humidity);
        return -1;
    }
    return 0;
}

int main(void) {
    int fd = -1;
    float temperature, humidity;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_DEV, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", HTU21D_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    while (running) {
        if (read_measurement(fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
            fflush(stdout);
        } else {
            fprintf(stderr, "Measurement failed; continuing.\n");
        }
        sleep(60);
    }

    if (fd >= 0) close(fd);
    return 0;
}

