#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_PIN_1 2
#define GPIO_PIN_2 3
#define POLL_INTERVAL_SEC 2

static volatile sig_atomic_t running = 1;

static void sigint_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the two GPIO lines */
    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line1) {
        perror("gpiod_chip_get_line (GPIO 2)");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        perror("gpiod_chip_get_line (GPIO 3)");
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line1, "gpio-toggle", 0) < 0) {
        perror("gpiod_line_request_output (GPIO 2)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, "gpio-toggle", 0) < 0) {
        perror("gpiod_line_request_output (GPIO 3)");
        goto cleanup;
    }

    /* Main loop: toggle every POLL_INTERVAL_SEC seconds until interrupted */
    while (running) {
        int val1 = gpiod_line_get_value(line1);
        int val2 = gpiod_line_get_value(line2);

        if (val1 < 0 || val2 < 0) {
            fprintf(stderr, "Error reading GPIO values (val1=%d, val2=%d)\n", val1, val2);
            goto cleanup;
        }

        /* Toggle both lines */
        int new_val1 = !val1;
        int new_val2 = !val2;

        if (gpiod_line_set_value(line1, new_val1) < 0) {
            perror("gpiod_line_set_value (GPIO 2)");
            goto cleanup;
        }

        if (gpiod_line_set_value(line2, new_val2) < 0) {
            perror("gpiod_line_set_value (GPIO 3)");
            goto cleanup;
        }

        printf("GPIO 2: %d, GPIO 3: %d\n", new_val1, new_val2);
        fflush(stdout);

        /* Sleep in 1-second increments so SIGINT is caught promptly */
        for (int i = 0; i < POLL_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip)  gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_BW_RATE 0x2C
#define ADXL345_REG_DATA_FORMAT 0x31

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_regs(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error setting reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "Error reading %d bytes from reg 0x%02X: %s\n", len, reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int adxl345_init(int fd) {
    if (i2c_write_reg8(fd, ADXL345_REG_POWER_CTL, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, ADXL345_REG_BW_RATE, 0x0A) < 0) return -1;
    if (i2c_write_reg8(fd, ADXL345_REG_DATA_FORMAT, 0x08) < 0) return -1;
    if (i2c_write_reg8(fd, ADXL345_REG_POWER_CTL, 0x08) < 0) return -1;
    return 0;
}

static int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_regs(fd, ADXL345_REG_DATAX0, buf, 6) < 0) return -1;
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", ADXL345_ADDRESS, strerror(errno));
        goto cleanup;
    }

    if (adxl345_init(fd) < 0) {
        fprintf(stderr, "Error initializing ADXL345\n");
        goto cleanup;
    }

    while (running) {
        int16_t x, y, z;
        if (read_acceleration(fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Error reading acceleration data\n");
            break;
        }
        printf("X: %d, Y: %d, Z: %d\n", x, y, z);
        usleep(100000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        i2c_write_reg8(fd, ADXL345_REG_POWER_CTL, 0x00);
        close(fd);
    }
    return ret;
}

