#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 22
#define PWM_PIN_3 27

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int pins[3] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3};
    int values[3] = {0, 0, 0};
    int i;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (is the pigpio daemon running?)\n");
        return EXIT_FAILURE;
    }

    for (i = 0; i < 3; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        for (i = 0; i < 3; i++) {
            if (gpioPWM(pins[i], values[i]) != 0) {
                fprintf(stderr, "Error: gpioPWM failed on GPIO %d\n", pins[i]);
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }
        printf("PWM on GPIO %d: %d, GPIO %d: %d, GPIO %d: %d\n",
               PWM_PIN_1, values[0], PWM_PIN_2, values[1], PWM_PIN_3, values[2]);
        fflush(stdout);

        values[0] = (values[0] + 1) % 256;
        values[1] = (values[1] + 1) % 256;
        values[2] = (values[2] + 1) % 256;

        sleep(1);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

