#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define TCS34725_ADDRESS 0x29

#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ENABLE_PON 0x01
#define TCS34725_ENABLE_AEN 0x02
#define TCS34725_ATIME 0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_ID 0x12
#define TCS34725_CDATAL 0x14
#define TCS34725_CDATAH 0x15
#define TCS34725_RDATAL 0x16
#define TCS34725_RDATAH 0x17
#define TCS34725_GDATAL 0x18
#define TCS34725_GDATAH 0x19
#define TCS34725_BDATAL 0x1A
#define TCS34725_BDATAH 0x1B

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { (uint8_t)(reg | TCS34725_COMMAND_BIT), value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    uint8_t cmd = (uint8_t)(reg | TCS34725_COMMAND_BIT);
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "Error setting reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "Error reading reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t cmd = (uint8_t)(reg | TCS34725_COMMAND_BIT);
    uint8_t buf[2];
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "Error setting reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int tcs34725_init(int fd) {
    uint8_t id = 0;
    if (i2c_read_reg8(fd, TCS34725_ID, &id) < 0) {
        return -1;
    }
    if (id != 0x44 && id != 0x4D) {
        fprintf(stderr, "Unexpected ID: 0x%02X (expected 0x44 or 0x4D)\n", id);
        return -1;
    }
    if (i2c_write_reg8(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON) < 0) return -1;
    usleep(3000);
    if (i2c_write_reg8(fd, TCS34725_ATIME, 0xFF) < 0) return -1;
    if (i2c_write_reg8(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0) return -1;
    if (i2c_write_reg8(fd, TCS34725_CONTROL, 0x03) < 0) return -1;
    return 0;
}

static int tcs34725_read_rgba(int fd, uint16_t *r, uint16_t *g, uint16_t *b, uint16_t *c) {
    if (i2c_read_reg16(fd, TCS34725_CDATAL, c) < 0) return -1;
    if (i2c_read_reg16(fd, TCS34725_RDATAL, r) < 0) return -1;
    if (i2c_read_reg16(fd, TCS34725_GDATAL, g) < 0) return -1;
    if (i2c_read_reg16(fd, TCS34725_BDATAL, b) < 0) return -1;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C address 0x%02X: %s\n", TCS34725_ADDRESS, strerror(errno));
        close(fd);
        return 1;
    }

    if (tcs34725_init(fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed.\n");
        close(fd);
        return 1;
    }

    while (running) {
        uint16_t r, g, b, c;
        if (tcs34725_read_rgba(fd, &r, &g, &b, &c) < 0) {
            fprintf(stderr, "Error reading RGBA values.\n");
            break;
        }
        printf("R: %5u, G: %5u, B: %5u, C: %5u\n", r, g, b, c);
        usleep(200000);
    }

    i2c_write_reg8(fd, TCS34725_ENABLE, 0x00);
    close(fd);
    return 0;
}

