#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#define SSD1306_I2C_ADDR 0x3C
#define SSD1306_WIDTH 128
#define SSD1306_HEIGHT 64
#define I2C_DEVICE "/dev/i2c-1"

static volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, unsigned char data) {
    if (write(fd, &data, 1) != 1) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int ssd1306_command(int fd, unsigned char cmd) {
    if (i2c_write_byte(fd, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, cmd) < 0) return -1;
    return 0;
}

static int ssd1306_data(int fd, unsigned char data) {
    if (i2c_write_byte(fd, 0x40) < 0) return -1;
    if (i2c_write_byte(fd, data) < 0) return -1;
    return 0;
}

static int ssd1306_init(int fd) {
    if (ssd1306_command(fd, 0xAE) < 0) return -1;
    if (ssd1306_command(fd, 0xD5) < 0) return -1;
    if (ssd1306_command(fd, 0x80) < 0) return -1;
    if (ssd1306_command(fd, 0xA8) < 0) return -1;
    if (ssd1306_command(fd, 0x3F) < 0) return -1;
    if (ssd1306_command(fd, 0xD3) < 0) return -1;
    if (ssd1306_command(fd, 0x00) < 0) return -1;
    if (ssd1306_command(fd, 0x40) < 0) return -1;
    if (ssd1306_command(fd, 0x8D) < 0) return -1;
    if (ssd1306_command(fd, 0x14) < 0) return -1;
    if (ssd1306_command(fd, 0x20) < 0) return -1;
    if (ssd1306_command(fd, 0x00) < 0) return -1;
    if (ssd1306_command(fd, 0xA1) < 0) return -1;
    if (ssd1306_command(fd, 0xC8) < 0) return -1;
    if (ssd1306_command(fd, 0xDA) < 0) return -1;
    if (ssd1306_command(fd, 0x12) < 0) return -1;
    if (ssd1306_command(fd, 0x81) < 0) return -1;
    if (ssd1306_command(fd, 0xCF) < 0) return -1;
    if (ssd1306_command(fd, 0xD9) < 0) return -1;
    if (ssd1306_command(fd, 0xF1) < 0) return -1;
    if (ssd1306_command(fd, 0xDB) < 0) return -1;
    if (ssd1306_command(fd, 0x40) < 0) return -1;
    if (ssd1306_command(fd, 0xA4) < 0) return -1;
    if (ssd1306_command(fd, 0xA6) < 0) return -1;
    if (ssd1306_command(fd, 0xAF) < 0) return -1;
    return 0;
}

static int ssd1306_clear(int fd) {
    for (int i = 0; i < SSD1306_WIDTH * SSD1306_HEIGHT / 8; i++) {
        if (ssd1306_data(fd, 0x00) < 0) return -1;
    }
    return 0;
}

static int ssd1306_display_text(int fd, int x, int y, const char *text) {
    if (ssd1306_command(fd, 0x21) < 0) return -1;
    if (ssd1306_command(fd, x) < 0) return -1;
    if (ssd1306_command(fd, SSD1306_WIDTH - 1) < 0) return -1;
    if (ssd1306_command(fd, 0x22) < 0) return -1;
    if (ssd1306_command(fd, y) < 0) return -1;
    if (ssd1306_command(fd, SSD1306_HEIGHT - 1) < 0) return -1;
    if (ssd1306_command(fd, 0x24) < 0) return -1;
    for (int i = 0; text[i] != '\0'; i++) {
        if (ssd1306_data(fd, text[i]) < 0) return -1;
    }
    return 0;
}

int main() {
    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C device %s: %s\n", I2C_DEVICE, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SSD1306_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SSD1306_I2C_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (ssd1306_init(fd) < 0) {
        fprintf(stderr, "SSD1306 initialization failed\n");
        close(fd);
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    while (running) {
        time_t rawtime;
        struct tm *timeinfo;
        char buffer[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(buffer, sizeof(buffer), "%H:%M:%S", timeinfo);

        if (ssd1306_clear(fd) < 0) {
            fprintf(stderr, "Failed to clear display\n");
            break;
        }
        if (ssd1306_display_text(fd, 0, 0, buffer) < 0) {
            fprintf(stderr, "Failed to display time\n");
            break;
        }
        if (ssd1306_command(fd, 0x26) < 0) break;
        if (ssd1306_command(fd, 0xFF) < 0) break;
        if (ssd1306_command(fd, 0x2E) < 0) break;
        if (ssd1306_command(fd, 0x00) < 0) break;

        sleep(1);
    }

    ssd1306_command(fd, 0xAE);
    close(fd);
    return 0;
}

