#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 8
#define PWM_PIN_2 9
#define PWM_PIN_3 11
#define PWM_PIN_4 18

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
            int duty = (i + 1) * 255 / 4;
            if (gpioPWM(pins[i], duty) != 0) {
                fprintf(stderr, "Failed to set PWM on GPIO %d\n", pins[i]);
            }
            printf("GPIO %d: %d\n", pins[i], duty);
        }
        fflush(stdout);
        sleep(1);
    }

    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 23
#define LED_PIN 24

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL, *led = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    led = gpiod_chip_get_line(chip, LED_PIN);
    if (!trig || !echo || !led) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        perror("gpiod_line_request_output trig");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        perror("gpiod_line_request_input echo");
        goto cleanup;
    }
    if (gpiod_line_request_output(led, "hcsr04-led", 0) < 0) {
        perror("gpiod_line_request_output led");
        goto cleanup;
    }

    while (running) {
        /* Ensure trigger is low for a clean pulse */
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value trig low");
            break;
        }
        usleep(2);

        /* 10us trigger pulse */
        if (gpiod_line_set_value(trig, 1) < 0) {
            perror("gpiod_line_set_value trig high");
            break;
        }
        usleep(10);
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value trig low");
            break;
        }

        /* Wait for echo rising edge (timeout 100ms) */
        int val;
        int timeout = 0;
        while ((val = gpiod_line_get_value(echo)) == 0 && running) {
            usleep(100);
            timeout += 100;
            if (timeout >= 100000) {
                fprintf(stderr, "Timeout waiting for echo high\n");
                goto cleanup;
            }
        }
        if (!running) break;

        struct timespec t_start, t_end;
        clock_gettime(CLOCK_MONOTONIC, &t_start);

        /* Wait for echo falling edge (timeout 100ms) */
        timeout = 0;
        while ((val = gpiod_line_get_value(echo)) == 1 && running) {
            usleep(100);
            timeout += 100;
            if (timeout >= 100000) {
                fprintf(stderr, "Timeout waiting for echo low\n");
                goto cleanup;
            }
        }
        if (!running) break;

        clock_gettime(CLOCK_MONOTONIC, &t_end);

        long long elapsed_ns = (t_end.tv_sec - t_start.tv_sec) * 1000000000LL +
                               (t_end.tv_nsec - t_start.tv_nsec);
        double distance = (double)elapsed_ns / 58.0;

        printf("Distance: %.2f cm\n", distance);
        fflush(stdout);

        /* Toggle LED */
        int led_val = gpiod_line_get_value(led);
        if (led_val < 0) {
            perror("gpiod_line_get_value led");
            break;
        }
        if (gpiod_line_set_value(led, led_val ? 0 : 1) < 0) {
            perror("gpiod_line_set_value led toggle");
            break;
        }

        usleep(200000);
    }

    ret = EXIT_SUCCESS;

cleanup:
