#include <pigpio.h>

#define PIN 18
#define DELAY_US 10000  /* 0.01 seconds */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (is the pigpio daemon running?)\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install signal handlers\n");
    }

    while (running) {
        /*
         * Set the strip to a solid red colour.
         * pigpio's gpioWrite expects a 0 or 1 for the level; we use 1 for red.
         * A full-spectrum RGB LED strip typically expects a 24-bit value
         * (8 bits per channel) but this example keeps it simple.
         */
        if (gpioWrite(PIN, 1) != 0) {
            fprintf(stderr, "Error: failed to write to GPIO %d\n", PIN);
            break;
        }
        gpioDelay(DELAY_US);
    }

    /* Ensure the pin is left in a safe low state before terminating */
    gpioWrite(PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

