#define DEVICE "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define FILENAME_FORMAT "image%03d.jpg"
#define NUM_IMAGES 10
#define DELAY_MS 50

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int capture_image(int fd, const char *filename) {
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    enum v4l2_buf_type type;
    unsigned char *buffer = NULL;
    int ret = -1;

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        return -1;
    }

    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        return -1;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        goto cleanup;
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        goto cleanup;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        goto streamoff;
    }

    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        goto streamoff;
    }

    if (fwrite(buffer, 1, buf.bytesused, fp) != buf.bytesused) {
        fprintf(stderr, "Error writing to file: %s\n", strerror(errno));
        fclose(fp);
        goto streamoff;
    }

    fclose(fp);
    ret = 0;

streamoff:
    if (xioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        fprintf(stderr, "Error stopping stream: %s\n", strerror(errno));
    }

cleanup:
    if (buffer && buffer != MAP_FAILED) {
        munmap(buffer, buf.length);
    }
    return ret;
}

int main(void) {
    int fd = -1;
    int i;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        return 1;
    }

    fd = open(DEVICE, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        fprintf(stderr, "Error opening device %s: %s\n", DEVICE, strerror(errno));
        return 1;
    }

    for (i = 0; i < NUM_IMAGES && running; i++) {
        char filename[64];
        snprintf(filename, sizeof(filename), FILENAME_FORMAT, i);
        if (capture_image(fd, filename) == -1) {
            fprintf(stderr, "Error capturing image %d\n", i);
            break;
        }
        printf("Captured image %s\n", filename);
        usleep(DELAY_MS * 1000);
    }

    if (fd != -1) {
        close(fd);
    }
    return 0;
}

