#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#define LCD_ADDR 0x27
#define LCD_CHR 1
#define LCD_CMD 0
#define LCD_BACKLIGHT 0x08
#define ENABLE 0x04

static int lcd_fd;
static volatile int keep_running = 1;

void handle_sig(int sig) {
    (void)sig;
    keep_running = 0;
}

void lcd_strobe(int data) {
    if (ioctl(lcd_fd, I2C_SLAVE, LCD_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        return;
    }
    usleep(1000);
    if (write(lcd_fd, &data, 1) != 1) {
        perror("write strobe");
    }
    usleep(1000);
}

void lcd_byte(int bits, int mode) {
    int high = mode | (bits & 0xF0) | LCD_BACKLIGHT;
    int low = mode | ((bits << 4) & 0xF0) | LCD_BACKLIGHT;
    lcd_strobe(high);
    lcd_strobe(low);
}

void lcd_init() {
    usleep(50000);
    lcd_byte(0x33, LCD_CMD);
    usleep(5000);
    lcd_byte(0x32, LCD_CMD);
    usleep(10000);
    lcd_byte(0x28, LCD_CMD);
    lcd_byte(0x0C, LCD_CMD);
    lcd_byte(0x06, LCD_CMD);
    lcd_byte(0x01, LCD_CMD);
    usleep(10000);
}

void lcd_string(const char *s) {
    while (*s) {
        lcd_byte(*s, LCD_CHR);
        s++;
    }
}

void lcd_clear() {
    lcd_byte(0x01, LCD_CMD);
    usleep(2000);
}

void lcd_set_cursor(int col, int row) {
    int offsets[] = {0x00, 0x40, 0x14, 0x54};
    if (row < 0 || row > 1) return;
    lcd_byte(0x80 | (col + offsets[row]), LCD_CMD);
}

void lcd_print_time() {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char buf[20];
    strftime(buf, sizeof(buf), "%H:%M:%S", t);
    lcd_clear();
    lcd_set_cursor(0, 0);
    lcd_string(buf);
}

int main() {
    signal(SIGINT, handle_sig);
    signal(SIGTERM, handle_sig);

    lcd_fd = open("/dev/i2c-1", O_RDWR);
    if (lcd_fd < 0) {
        perror("open /dev/i2c-1");
        return 1;
    }

    lcd_init();

    while (keep_running) {
        lcd_print_time();
        sleep(10);
    }

    lcd_clear();
    lcd_string("Exiting...");
    close(lcd_fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68

#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_byte: write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_burst: write reg failed: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "i2c_read_burst: read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    int fd = -1;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open %s failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n", MPU6050_ADDR, strerror(errno));
        goto cleanup;
    }

    if (i2c_write_byte(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "MPU6050 not responding at 0x%02X\n", MPU6050_ADDR);
        goto cleanup;
    }

    for (int i = 0; i < 100 && running; i++) {
        uint8_t buf[6];
        if (i2c_read_burst(fd, ACCEL_XOUT_H, buf, 6) < 0) {
            goto cleanup;
        }
        int16_t ax = (int16_t)((buf[0] << 8) | buf[1]);
        int16_t ay = (int16_t)((buf[2] << 8) | buf[3]);
        int16_t az = (int16_t)((buf[4] << 8) | buf[5]);
        printf("Accel: X=%d, Y=%d, Z=%d\n", ax, ay, az);
        fflush(stdout);
        usleep(10000);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return rc;
}

