#include <pigpio.h>
#include <MQTTClient.h>

#define MQTT_BROKER "tcp://localhost:1883"
#define MQTT_TOPIC "sensor/data"
#define MQTT_CLIENT_ID "rpi_sensor_publisher"
#define MQTT_TIMEOUT_MS 1000

static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(int argc, char *argv[]) {
    int rc;
    MQTTClient client;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    int sensor_value;

    if (argc > 1) {
        fprintf(stderr, "Usage: %s [broker_address]\n", argv[0]);
        return 1;
    }

    if (argc == 2) {
        MQTT_BROKER = argv[1];
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if ((rc = MQTTClient_create(&client, MQTT_BROKER, MQTT_CLIENT_ID,
                                MQTTCLIENT_PERSISTENCE_NONE, NULL)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to create MQTT client, return code %d\n", rc);
        gpioTerminate();
        return 1;
    }

    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    if ((rc = MQTTClient_connect(client, &conn_opts)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker, return code %d\n", rc);
        MQTTClient_destroy(&client);
        gpioTerminate();
        return 1;
    }

    sensor_value = gpioRead(17);
    if (sensor_value < 0) {
        fprintf(stderr, "Failed to read sensor on GPIO 17\n");
        MQTTClient_disconnect(client, MQTT_TIMEOUT_MS);
        MQTTClient_destroy(&client);
        gpioTerminate();
        return 1;
    }

    pubmsg.payload = (void *)"1";
    pubmsg.payloadlen = 1;
    pubmsg.qos = 0;
    pubmsg.retained = 0;

    if ((rc = MQTTClient_publishMessage(client, MQTT_TOPIC, &pubmsg, NULL)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message, return code %d\n", rc);
    }

    MQTTClient_disconnect(client, MQTT_TIMEOUT_MS);
    MQTTClient_destroy(&client);
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_RANGE 255
#define PWM_FREQ 1000
#define STEP 10

static volatile sig_atomic_t running = 1;

static void sigint_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    int rc;

    /* Install SIGINT handler for clean shutdown */
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "pigpio initialisation failed (code %d).\n", rc);
        fprintf(stderr, "Check that pigpiod is not running and you have root/permissions.\n");
        return EXIT_FAILURE;
    }

    /* Configure PWM on GPIO 18 */
    rc = gpioSetMode(PWM_PIN, PI_OUTPUT);
    if (rc < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output (code %d).\n", PWM_PIN, rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    rc = gpioSetPWMrange(PWM_PIN, PWM_RANGE);
    if (rc < 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d (code %d).\n", PWM_PIN, rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    rc = gpioSetPWMfrequency(PWM_PIN, PWM_FREQ);
    if (rc < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d (code %d).\n", PWM_PIN, rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure PWM is off at start */
    rc = gpioPWM(PWM_PIN, 0);
    if (rc < 0) {
        fprintf(stderr, "Failed to initialise PWM on GPIO %d (code %d).\n", PWM_PIN, rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int duty = 0;
    while (running) {
        rc = gpioPWM(PWM_PIN, duty);
        if (rc < 0) {
            fprintf(stderr, "Failed to set PWM duty cycle on GPIO %d (code %d).\n", PWM_PIN, rc);
            break;
        }

        printf("PWM duty cycle: %d\n", duty);
        fflush(stdout);

        duty += STEP;
        if (duty >= PWM_RANGE) {
            duty = 0;
        }

        /* Sleep 5 seconds, but wake early on signal */
        for (int i = 0; i < 50 && running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    /* Clean shutdown: turn off PWM and release pigpio */
    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define CONSUMER "hcsr04"

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trig) {
        perror("gpiod_chip_get_line(trigger)");
        goto cleanup;
    }
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        perror("gpiod_chip_get_line(echo)");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(trigger)");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, CONSUMER) < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }

    while (running) {
        /* Ensure trigger is low for a clean pulse */
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value(trig low)");
            break;
        }
        usleep(2);

        /* 10-microsecond trigger pulse */
        if (gpiod_line_set_value(trig, 1) < 0) {
            perror("gpiod_line_set_value(trig high)");
            break;
        }
        usleep(10);
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value(trig low)");
            break;
        }

        /* Wait for echo rising edge (timeout 100 ms) */
        int val;
        int waited = 0;
        while ((val = gpiod_line_get_value(echo)) == 0 && running) {
            usleep(100);
            waited += 100;
            if (waited >= 100000) {
                fprintf(stderr, "Timeout waiting for echo high\n");
                goto cleanup;
            }
        }
        if (!running) break;

        /* Measure echo high duration */
        struct timespec t_start, t_now;
        clock_gettime(CLOCK_MONOTONIC, &t_start);
        while ((val = gpiod_line_get_value(echo)) == 1 && running) {
            clock_gettime(CLOCK_MONOTONIC, &t_now);
            long elapsed_us = (t_now.tv_sec - t_start.tv_sec) * 1000000L +
                              (t_now.tv_nsec - t_start.tv_nsec) / 1000L;
            if (elapsed_us > 300000) {
                fprintf(stderr, "Timeout waiting for echo low (%ld us)\n", elapsed_us);
                goto cleanup;
            }
            usleep(100);
        }
        if (!running) break;

        clock_gettime(CLOCK_MONOTONIC, &t_now);
        long elapsed_us = (t_now.tv_sec - t_start.tv_sec) * 1000000L +
                          (t_now.tv_nsec - t_start.tv_nsec) / 1000L;

        float distance = (elapsed_us / 2.0f) * 0.0343f;
        printf("Distance: %.2f cm\n", distance);
        fflush(stdout);

        usleep(200000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PINS {17, 18, 22, 23}
#define NUM_PINS 4
#define PWM_RANGE 255
#define PWM_FREQ 1000
#define STEP 10

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int pins[NUM_PINS] = PWM_PINS;
    int values[NUM_PINS];
    int i;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (i = 0; i < NUM_PINS; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Failed to set PWM range on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(pins[i], PWM_FREQ) != 0) {
            fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        values[i] = 0;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        for (i = 0; i < NUM_PINS; i++) {
            if (gpioPWM(pins[i], values[i]) != 0) {
                fprintf(stderr, "Failed to set PWM on GPIO %d\n", pins[i]);
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }
        printf("PWM values: %d, %d, %d, %d\n", values[0], values[1], values[2], values[3]);
        fflush(stdout);

        for (i = 0; i < NUM_PINS; i++) {
            values[i] = (values[i] + STEP) % (PWM_RANGE + 1);
        }

        gpioDelay(100000); /* 0.1 seconds */
    }

    /* Clean shutdown: turn off all PWM outputs */
    for (i = 0; i < NUM_PINS; i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

