#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define ADS1115_ADDR 0x48
#define ADS1115_CONVERSION_REG 0x00
#define ADS1115_CONFIG_REG 0x01

#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor/ads1115"
#define MQTT_CLIENT_ID "ads1115_publisher"

static volatile int running = 1;
static MQTTClient client;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_ads1115(int handle, int channel) {
    if (channel < 0 || channel > 3) return -1;
    int config = 0x8000 | (channel << 12) | 0x4000 | 0x0080 | 0x0003;
    char buf[2];
    buf[0] = (config >> 8) & 0xFF;
    buf[1] = config & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) < 0) return -1;
    gpioDelay(10000);
    if (i2cReadDevice(handle, buf, 2) < 0) return -1;
    return (buf[0] << 8) | buf[1];
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    int handle = i2cOpen(1, ADS1115_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "i2cOpen failed\n");
        gpioTerminate();
        return 1;
    }

    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    MQTTClient_createOptions create_opts = MQTTClient_createOptions_initializer;
    create_opts.MQTTVersion = MQTTCLIENT_PROTOCOL_V311;

    if (MQTTClient_create(&client, MQTT_BROKER, MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "MQTTClient_create failed\n");
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    if (MQTTClient_connect(client, &conn_opts) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "MQTTClient_connect failed\n");
        MQTTClient_destroy(&client);
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    for (int i = 0; i < 10 && running; i++) {
        int val = read_ads1115(handle, 0);
        if (val < 0) {
            fprintf(stderr, "Read error\n");
            continue;
        }
        char payload[32];
        snprintf(payload, sizeof(payload), "%d", val);
        pubmsg.payload = payload;
        pubmsg.payloadlen = (int)strlen(payload);
        pubmsg.qos = 0;
        pubmsg.retained = 0;
        if (MQTTClient_publishMessage(client, MQTT_TOPIC, &pubmsg, NULL) != MQTTCLIENT_SUCCESS) {
            fprintf(stderr, "Publish failed\n");
        }
        gpioDelay(1000000);
    }

    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    i2cClose(handle);
    gpioTerminate();
    return 0;
}

