#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <signal.h>

#define BAUDRATE B115200
#define SERIAL_DEVICE "/dev/ttyAMA0"

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main() {
    int fd;
    struct termios tty;
    char buffer[256];
    ssize_t bytes_read;

    // Set up signal handler for graceful exit
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    // Open serial port
    fd = open(SERIAL_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening serial port");
        return 1;
    }

    // Configure serial port
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return 1;
    }

    cfsetospeed(&tty, BAUDRATE);
    cfsetispeed(&tty, BAUDRATE);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8; // 8 data bits
    tty.c_cflag |= (CLOCAL | CREAD);            // Enable receiver, ignore modem control
    tty.c_cflag &= ~(PARENB | PARODD);          // No parity
    tty.c_cflag &= ~CSTOPB;                     // 1 stop bit
    tty.c_cflag &= ~CRTSCTS;                    // No hardware flow control

    tty.c_iflag &= ~(IXON | IXOFF | IXANY);     // No software flow control
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);

    tty.c_lflag = 0; // Non-canonical mode, no echo, no signals

    tty.c_oflag = 0; // Raw output

    tty.c_cc[VMIN] = 1;  // Read at least 1 byte
    tty.c_cc[VTIME] = 5; // Timeout 0.5s (5 * 0.1s)

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return 1;
    }

    // Flush any pending data
    tcflush(fd, TCIOFLUSH);

    printf("Serial port initialized successfully.\n");

    // Main loop
    while (keep_running) {
        bytes_read = read(fd, buffer, sizeof(buffer) - 1);
        if (bytes_read > 0) {
            buffer[bytes_read] = '\0';
            printf("Received: %s", buffer);
            fflush(stdout);
        } else if (bytes_read < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                // Timeout, no data available
                continue;
            }
            perror("Error reading from serial port");
            break;
        } else {
            // bytes_read == 0, should not happen with VMIN=1
            break;
        }
    }

    // Cleanup
    close(fd);
    printf("\nSerial port closed.\n");

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_XOUT_L 0x3C
#define ACCEL_YOUT_H 0x3D
#define ACCEL_YOUT_L 0x3E
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_ZOUT_L 0x40

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error setting register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "Error reading %zu bytes from register 0x%02X: %s\n", len, reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int16_t combine_bytes(uint8_t high, uint8_t low) {
    return (int16_t)((high << 8) | low);
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus access for 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        goto cleanup;
    }

    if (i2c_write_byte(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "MPU6050 not detected at address 0x%02X\n", MPU6050_ADDR);
        goto cleanup;
    }

    while (running) {
        uint8_t buf[6];
        if (i2c_read_burst(fd, ACCEL_XOUT_H, buf, 6) < 0) {
            goto cleanup;
        }

        int16_t accel_x = combine_bytes(buf[0], buf[1]);
        int16_t accel_y = combine_bytes(buf[2], buf[3]);
        int16_t accel_z = combine_bytes(buf[4], buf[5]);

        printf("Accel X: %d, Y: %d, Z: %d\n", accel_x, accel_y, accel_z);
        fflush(stdout);

        usleep(100000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BMP280_I2C_ADDR 0x76
#define I2C_DEV "/dev/i2c-1"

#define BMP280_REG_ID 0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_TEMP_MSB 0xFA

#define BMP280_CHIP_ID 0x58
#define BMP280_RESET_CMD 0xB6

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int bmp280_init(int fd) {
    uint8_t id;
    if (i2c_read_reg(fd, BMP280_REG_ID, &id) != 0) {
        fprintf(stderr, "Error: Failed to read chip ID: %s\n", strerror(errno));
        return -1;
    }
    if (id != BMP280_CHIP_ID) {
        fprintf(stderr, "Error: Unexpected chip ID 0x%02X (expected 0x%02X)\n", id, BMP280_CHIP_ID);
        return -1;
    }
    if (i2c_write_reg(fd, BMP280_REG_RESET, BMP280_RESET_CMD) != 0) {
        fprintf(stderr, "Error: Failed to reset BMP280: %s\n", strerror(errno));
        return -1;
    }
    usleep(2000);
    if (i2c_write_reg(fd, BMP280_REG_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to write config: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_write_reg(fd, BMP280_REG_CTRL_MEAS, 0x27) != 0) {
        fprintf(stderr, "Error: Failed to write ctrl_meas: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int bmp280_read_pressure(int fd, float *pressure) {
    uint8_t buf[3];
    if (i2c_read_block(fd, BMP280_REG_PRESS_MSB, buf, 3) != 0) {
        fprintf(stderr, "Error: Failed to read pressure data: %s\n", strerror(errno));
        return -1;
    }
    int32_t raw = ((int32_t)buf[0] << 12) | ((int32_t)buf[1] << 4) | ((int32_t)buf[2] >> 4);
    *pressure = (float)raw / 256.0f;
    return 0;
}

static int bmp280_read_temperature(int fd, float *temperature) {
    uint8_t buf[3];
    if (i2c_read_block(fd, BMP280_REG_TEMP_MSB, buf, 3) != 0) {
        fprintf(stderr, "Error: Failed to read temperature data: %s\n", strerror(errno));
        return -1;
    }
    int32_t raw = ((int32_t)buf[0] << 12) | ((int32_t)buf[1] << 4) | ((int32_t)buf[2] >> 4);
    *temperature = (float)raw / 256.0f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error: Failed to open %s: %s\n", I2C_DEV, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
        fprintf(stderr, "Error: Failed to set I2C slave address 0x%02X: %s\n", BMP280_I2C_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (bmp280_init(fd) != 0) {
        fprintf(stderr, "Error: BMP280 initialization failed.\n");
        close(fd);
        return 1;
    }

    while (running) {
        float pressure, temperature;
        if (bmp280_read_pressure(fd, &pressure) == 0 && bmp280_read_temperature(fd, &temperature) == 0) {
            printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data.\n");
        }
        sleep(5);
    }

    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN 4
#define PWM_RANGE 255
#define PWM_DUTY 128

static volatile sig_atomic_t running = 1;

static void sigint_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed (is the pigpiod daemon running?)\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioPWM(PWM_PIN, PWM_DUTY) != 0) {
        fprintf(stderr, "Failed to set PWM duty cycle on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("PWM output on GPIO %d: range=%d, duty=%d\n", PWM_PIN, PWM_RANGE, PWM_DUTY);
    fflush(stdout);

    while (running) {
        gpioDelay(100000); /* 100 ms */
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

