        gpiod_line_request_output(line13, "gpio13_out", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    printf("GPIO 5, 6, 13 set to LOW\n");
    fflush(stdout);

    while (running) {
        sleep(1);
    }

    printf("\nShutting down...\n");
    fflush(stdout);

    gpiod_line_set_value(line5, 0);
    gpiod_line_set_value(line6, 0);
    gpiod_line_set_value(line13, 0);

    ret = EXIT_SUCCESS;

cleanup:
    if (line5) gpiod_line_release(line5);
    if (line6) gpiod_line_release(line6);
    if (line13) gpiod_line_release(line13);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <paho-mqtt-c/MQTTClient.h>

#define MQTT_BROKER "tcp://localhost:1883"
#define MQTT_TOPIC "sensor/data"
#define MQTT_CLIENT_ID "rpi_sensor_publisher"
#define MQTT_TIMEOUT_MS 1000

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

int main(int argc, char *argv[]) {
    MQTTClient client;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    MQTTClient_deliveryToken token;
    int rc;

    if (argc > 1) {
        fprintf(stderr, "Usage: %s [broker_address]\n", argv[0]);
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (argc == 2) {
        MQTT_BROKER = argv[1];
    }

    rc = MQTTClient_create(&client, MQTT_BROKER, MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to create MQTT client: %s\n", MQTTClient_strerror(rc));
        return 1;
    }

    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    rc = MQTTClient_connect(client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker: %s\n", MQTTClient_strerror(rc));
        MQTTClient_destroy(&client);
        return 1;
    }

    char payload[100];
    snprintf(payload, sizeof(payload), "{\"temperature\": 25.5, \"humidity\": 60.2}");

    pubmsg.payload = payload;
    pubmsg.payloadlen = (int)strlen(payload);
    pubmsg.qos = 0;
    pubmsg.retained = 0;

    rc = MQTTClient_publishMessage(client, MQTT_TOPIC, &pubmsg, &token);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message: %s\n", MQTTClient_strerror(rc));
        MQTTClient_disconnect(client, MQTT_TIMEOUT_MS);
        MQTTClient_destroy(&client);
        return 1;
    }

    printf("Published: %s\n", payload);

    MQTTClient_disconnect(client, MQTT_TIMEOUT_MS);
    MQTTClient_destroy(&client);

    return 0;
}

#include <stdio.h>
