#define PWM_PINS {2, 3, 18, 23, 24}
#define NUM_PINS 5

static volatile sig_atomic_t running = 1;

static void sigint_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    int pins[NUM_PINS] = PWM_PINS;
    int i;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (is the pigpio daemon running?)\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    for (i = 0; i < NUM_PINS; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioPWM(pins[i], 128) != 0) {
            fprintf(stderr, "Error: gpioPWM failed for pin %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        printf("PWM on GPIO %d set to 128\n", pins[i]);
    }

