#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 22
#define PWM_PIN_3 27

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN_1, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN_1);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN_2, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN_2);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN_3, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN_3);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int pwm_values[3] = {0, 0, 0};
    int pwm_pins[3]   = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3};

    while (running) {
        for (int i = 0; i < 3; i++) {
            if (gpioPWM(pwm_pins[i], pwm_values[i]) != 0) {
                fprintf(stderr, "Failed to set PWM on GPIO %d\n", pwm_pins[i]);
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }

        printf("PWM on GPIO %d: %d, GPIO %d: %d, GPIO %d: %d\n",
               PWM_PIN_1, pwm_values[0],
               PWM_PIN_2, pwm_values[1],
               PWM_PIN_3, pwm_values[2]);
        fflush(stdout);

        for (int i = 0; i < 3; i++) {
            pwm_values[i] = (pwm_values[i] + 1) % 256;
        }

        gpioDelay(50000); /* 50 ms in microseconds */
    }

    /* Clean shutdown: turn off all PWM outputs */
    for (int i = 0; i < 3; i++) {
        gpioPWM(pwm_pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <signal.h>

#define DEVICE "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define FILENAME_FORMAT "image%03d.jpg"
#define NUM_IMAGES 10

static volatile sig_atomic_t stop = 0;

static void sig_handler(int sig) {
    (void)sig;
    stop = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(int *fd) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;

    *fd = open(DEVICE, O_RDWR);
    if (*fd < 0) {
        fprintf(stderr, "Error opening device %s: %s\n", DEVICE, strerror(errno));
        return -1;
    }

    if (xioctl(*fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(*fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        close(*fd);
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(*fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(*fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    return 0;
}

static int capture_image(int fd, const char *filename) {
    struct v4l2_buffer buf;
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        return -1;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        return -1;
    }

    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        return -1;
    }

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        return -1;
    }

    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        xioctl(fd, VIDIOC_QBUF, &buf);
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        return -1;
    }

    if (fwrite(buf.m.userptr, buf.length, 1, fp) != 1) {
        fprintf(stderr, "Error writing to file: %s\n", strerror(errno));
        fclose(fp);
        remove(filename);
        xioctl(fd, VIDIOC_QBUF, &buf);
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        return -1;
    }

    fclose(fp);
    xioctl(fd, VIDIOC_QBUF, &buf);
    xioctl(fd, VIDIOC_STREAMOFF, &type);
    return 0;
}

int main(void) {
    int fd = -1;
    int ret = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_camera(&fd) < 0) {
        return 1;
    }

    for (int i = 0; i < NUM_IMAGES && !stop; i++) {
        char filename[64];
        snprintf(filename, sizeof(filename), FILENAME_FORMAT, i);
        printf("Capturing image %s...\n", filename);
        if (capture_image(fd, filename) < 0) {
            fprintf(stderr, "Error capturing image %d\n", i);
            ret = 1;
            break;
        }
        sleep(1);
    }

    if (fd >= 0) {
        close(fd);
    }

    if (ret == 0) {
        printf("Program finished.\n");
    }
    return ret;
}

