#include <signal.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_RANGE 100
#define PWM_FREQ 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) != PWM_FREQ) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioPWM(PWM_PIN, 50) != 0) {
        fprintf(stderr, "Failed to set PWM duty cycle on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("PWM output on GPIO %d: 50%% duty cycle\n", PWM_PIN);
    fflush(stdout);

    while (running) {
        gpioDelay(100000);
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 27
#define POLL_INTERVAL_SEC 2

static volatile sig_atomic_t running = 1;

static void sigint_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request the line as output, initial value LOW */
    if (gpiod_line_request_output(line, "gpio-output", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    printf("GPIO %d set to LOW. Press Ctrl+C to exit.\n", GPIO_LINE);
    fflush(stdout);

    /* Main loop: toggle every POLL_INTERVAL_SEC seconds */
    while (running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }

        val = !val;
        if (gpiod_line_set_value(line, val) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }

        printf("GPIO %d set to %s\n", GPIO_LINE, val ? "HIGH" : "LOW");
        fflush(stdout);

        /* Sleep in 1-second increments so SIGINT is caught promptly */
        for (int i = 0; i < POLL_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PINS {8, 9, 10, 11, 17}
#define NUM_PINS 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int pins[NUM_PINS] = PWM_PINS;
    int i;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    for (i = 0; i < NUM_PINS; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioPWM(pins[i], 0) != 0) {
            fprintf(stderr, "Failed to initialise PWM on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("Driving PWM on GPIO 8, 9, 10, 11, 17 for 1 second...\n");
    fflush(stdout);

    while (running) {
        for (i = 0; i < NUM_PINS; i++) {
            if (gpioPWM(pins[i], 128) != 0) {
                fprintf(stderr, "Failed to set PWM on GPIO %d\n", pins[i]);
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }
        gpioDelay(1000000);
        if (!running) break;
        for (i = 0; i < NUM_PINS; i++) {
            if (gpioPWM(pins[i], 0) != 0) {
                fprintf(stderr, "Failed to clear PWM on GPIO %d\n", pins[i]);
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }
        gpioDelay(1000000);
    }

    for (i = 0; i < NUM_PINS; i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

