#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define DHT22_PIN 4
#define MAX_TIMINGS 85
#define DHT22_TIMEOUT_US 200

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static int wait_for_level(struct gpiod_line *line, int target, int timeout_us) {
    int elapsed = 0;
    while (elapsed < timeout_us) {
        if (gpiod_line_get_value(line) == target) return 0;
        usleep(1);
        elapsed++;
    }
    return -1;
}

static int read_dht22(struct gpiod_line *line, float *humidity, float *temperature) {
    uint8_t data[5] = {0, 0, 0, 0, 0};
    int i, j = 0;

    if (gpiod_line_request_output(line, "dht22", 1) < 0) return -1;
    usleep(500);
    gpiod_line_set_value(line, 0);
    usleep(20000);
    gpiod_line_set_value(line, 1);
    usleep(40);
    if (gpiod_line_request_input(line, "dht22") < 0) return -1;

    if (wait_for_level(line, 0, DHT22_TIMEOUT_US) < 0) return -2;
    if (wait_for_level(line, 1, DHT22_TIMEOUT_US) < 0) return -2;
    if (wait_for_level(line, 0, DHT22_TIMEOUT_US) < 0) return -2;

    for (i = 0; i < MAX_TIMINGS; i++) {
        int count = 0;
        while (gpiod_line_get_value(line) == 0) {
            if (++count > 255) return -2;
            usleep(1);
        }
        count = 0;
        while (gpiod_line_get_value(line) == 1) {
            if (++count > 255) return -2;
            usleep(1);
        }
        data[j / 8] <<= 1;
        if (count > 16) data[j / 8] |= 1;
        j++;
        if (j == 40) break;
    }

    if (j < 40) return -2;
    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) return -3;

    uint16_t raw_h = (data[0] << 8) | data[1];
    uint16_t raw_t = (data[2] << 8) | data[3];
    *humidity = (float)raw_h / 10.0f;
    *temperature = (float)(raw_t & 0x7FFF) / 10.0f;
    if (raw_t & 0x8000) *temperature = -*temperature;

    if (*humidity < 0.0f || *humidity > 100.0f || *temperature < -40.0f || *temperature > 80.0f) return -4;
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    float humidity, temperature;
    int rc;

    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, DHT22_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    rc = read_dht22(line, &humidity, &temperature);
    if (rc == 0) {
        printf("Humidity: %.1f%%, Temperature: %.1fC\n", humidity, temperature);
    } else {
        fprintf(stderr, "DHT22 read failed (code %d)\n", rc);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return (rc == 0) ? EXIT_SUCCESS : EXIT_FAILURE;
}

