        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", PCF8574_ADDR, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

int write_display(int fd, int value) {
    if (value < 0 || value > 15) {
        fprintf(stderr, "Invalid display value %d (must be 0-15)\n", value);
        return -1;
    }
    unsigned char buf[1] = { (unsigned char)(value & 0x0F) };
    if (write(fd, buf, 1) != 1) {
        fprintf(stderr, "Failed to write to display: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
