    int idx = 0;

    while (keep_running) {
        values[idx] = (values[idx] + 1) % 16;
        if (write_display(i2c_fd, values[idx]) < 0) {
            break;
        }
        idx = (idx + 1) % NUM_DISPLAYS;
        usleep(500000);
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return EXIT_SUCCESS;
}

