#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define CONSUMER    "hcsr04"

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trig) {
        perror("gpiod_chip_get_line(trigger)");
        goto cleanup;
    }
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        perror("gpiod_chip_get_line(echo)");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(trigger)");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, CONSUMER) < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }

    while (running) {
        /* Ensure trigger is low for a clean pulse */
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value(trig low)");
            break;
        }
        usleep(2);

        /* 10-microsecond trigger pulse */
        if (gpiod_line_set_value(trig, 1) < 0) {
            perror("gpiod_line_set_value(trig high)");
            break;
        }
        usleep(10);
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value(trig low)");
            break;
        }

        /* Wait for echo rising edge (timeout 100 ms) */
        int val;
        for (int i = 0; i < 100; i++) {
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                perror("gpiod_line_get_value(echo)");
                goto cleanup;
            }
            if (val == 1) break;
            usleep(1000);
        }
        if (val != 1) {
            fprintf(stderr, "HC-SR04: no echo received (sensor absent or not responding)\n");
            goto cleanup;
        }

        /* Measure echo high duration */
        struct timespec t0, t1;
        clock_gettime(CLOCK_MONOTONIC, &t0);
        for (int i = 0; i < 100; i++) {
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                perror("gpiod_line_get_value(echo)");
                goto cleanup;
            }
            if (val == 0) break;
            usleep(1000);
        }
        clock_gettime(CLOCK_MONOTONIC, &t1);
        if (val != 0) {
            fprintf(stderr, "HC-SR04: echo stuck high (timeout)\n");
            goto cleanup;
        }

        double elapsed_us = (t1.tv_sec - t0.tv_sec) * 1e6 +
                            (t1.tv_nsec - t0.tv_nsec) / 1e3;
        double distance = elapsed_us / 58.0;

        printf("Distance: %.2f cm\n", distance);
        fflush(stdout);

        sleep(1);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return rc;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 8
#define PWM_PIN_2 9
#define PWM_PIN_3 11
#define PWM_PIN_4 18

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4};
    int num_pins = (int)(sizeof(pins) / sizeof(pins[0]));

    for (int i = 0; i < num_pins; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        for (int i = 0; i < num_pins; i++) {
            int duty = (i + 1) * 255 / num_pins;
            if (gpioPWM(pins[i], duty) != 0) {
                fprintf(stderr, "Failed to set PWM on GPIO %d\n", pins[i]);
            }
            printf("GPIO %d: %d\n", pins[i], duty);
        }
        fflush(stdout);
        sleep(1);
    }

    for (int i = 0; i < num_pins; i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

