        data = (1 << i);
        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            if (i2c_write_byte(fd, data) == 0) {
                break;
            }
            if (errno == EREMOTEIO || errno == EIO) {
                fprintf(stderr, "Device not responding (attempt %d/%d)\n", attempt + 1, MAX_RETRIES);
                continue;
            }
            perror("write");
            goto cleanup;
        }
        if (!running) break;
        usleep(100000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

