#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PINS {17, 18, 22, 27}
#define NUM_PINS 4

static volatile sig_atomic_t running = 1;

static void sigint_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    int pins[NUM_PINS] = PWM_PINS;
    int i;

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed (is the pigpiod daemon running?)\n");
        return EXIT_FAILURE;
    }

    for (i = 0; i < NUM_PINS; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioPWM(pins[i], 0) != 0) {
            fprintf(stderr, "Failed to initialise PWM on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("PWM pins: ");
    for (i = 0; i < NUM_PINS; i++) {
        printf("%d ", pins[i]);
    }
    printf("\n");
    fflush(stdout);

    while (running) {
        for (i = 0; i < NUM_PINS; i++) {
            if (gpioPWM(pins[i], 128) != 0) {
                fprintf(stderr, "Failed to set PWM on GPIO %d\n", pins[i]);
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }
        gpioDelay(100000);
        for (i = 0; i < NUM_PINS; i++) {
            if (gpioPWM(pins[i], 0) != 0) {
                fprintf(stderr, "Failed to clear PWM on GPIO %d\n", pins[i]);
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }
        gpioDelay(100000);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

