    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    for (int cycle = 0; cycle < CYCLES && running; cycle++) {
        for (int i = 0; i < NUM_PIXELS && running; i++) {
            int red = (i * 255 / NUM_PIXELS) % 256;
            int green = (i * 128 / NUM_PIXELS) % 256;
            int blue = (i * 64 / NUM_PIXELS) % 256;

            gpioWrite(PIN, red << 16 | green << 8 | blue);
            gpioDelay(DELAY_US);
        }
    }

    gpioWrite(PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
