        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request the line as output, initial value LOW */
    if (gpiod_line_request_output(line, "gpio18-output", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    printf("GPIO %d set to LOW. Press Ctrl+C to exit.\n", GPIO_LINE);

    /* Main loop: toggle every POLL_INTERVAL_SEC seconds */
    while (running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }

        val = !val;
        if (gpiod_line_set_value(line, val) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }

        printf("GPIO %d set to %d\n", GPIO_LINE, val);

        /* Sleep in 1-second increments so SIGINT is caught promptly */
        for (int i = 0; i < POLL_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define W1_DEVICES "/sys/bus/w1/devices"
#define W1_DEVICE_DIR_PREFIX "28-"
#define W1_DEVICE_DIR_LEN 3
#define W1_TEMP_FILE "w1_slave"
#define W1_TEMP_FILE_LEN 10
#define W1_READING_LEN 128
#define W1_ERROR_VALUE -1000.0f

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int find_w1_device(char *device_path, size_t path_len) {
    FILE *dir = fopen(W1_DEVICES, "r");
    if (!dir) {
        fprintf(stderr, "Error opening %s: %s\n", W1_DEVICES, strerror(errno));
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), dir)) {
        if (strncmp(line, W1_DEVICE_DIR_PREFIX, W1_DEVICE_DIR_LEN) == 0) {
            size_t len = strlen(line);
            if (len > 0 && line[len - 1] == '\n') {
                line[len - 1] = '\0';
            }
            snprintf(device_path, path_len, "%s/%s/%s", W1_DEVICES, line, W1_TEMP_FILE);
            fclose(dir);
            return 0;
        }
    }

    fclose(dir);
    fprintf(stderr, "No DS18B20 device found in %s\n", W1_DEVICES);
    return -1;
}

static float read_temperature(const char *device_path) {
    FILE *fp = fopen(device_path, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", device_path, strerror(errno));
        return W1_ERROR_VALUE;
    }

    char buffer[W1_READING_LEN];
    size_t total = 0;
    while (total < W1_READING_LEN - 1) {
        size_t n = fread(buffer + total, 1, W1_READING_LEN - 1 - total, fp);
        if (n == 0) {
            if (ferror(fp)) {
                fprintf(stderr, "Error reading %s: %s\n", device_path, strerror(errno));
                fclose(fp);
                return W1_ERROR_VALUE;
            }
            break;
        }
        total += n;
        buffer[total] = '\0';
        if (strstr(buffer, "YES") != NULL) {
            break;
        }
    }
    fclose(fp);

    if (strstr(buffer, "YES") == NULL) {
        fprintf(stderr, "Sensor CRC check failed for %s\n", device_path);
        return W1_ERROR_VALUE;
    }

    char *temp_str = strstr(buffer, "t=");
    if (!temp_str) {
        fprintf(stderr, "Temperature data not found in %s\n", device_path);
        return W1_ERROR_VALUE;
    }

    errno = 0;
    long temp_raw = strtol(temp_str + 2, NULL, 10);
    if (errno != 0) {
        fprintf(stderr, "Error converting temperature in %s\n", device_path);
        return W1_ERROR_VALUE;
    }

    return (float)temp_raw / 1000.0f;
}

int main(void) {
    char device_path[256];
    if (find_w1_device(device_path, sizeof(device_path)) != 0) {
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n", strerror(errno));
    }

    for (int i = 0; i < 3 && g_running; i++) {
        float temp = read_temperature(device_path);
        if (temp == W1_ERROR_VALUE) {
            fprintf(stderr, "Failed to read temperature after %d attempts\n", i + 1);
            return EXIT_FAILURE;
        }
        printf("Temperature: %.2f C\n", temp);
        fflush(stdout);
        sleep(5);
    }

    return EXIT_SUCCESS;
}

