#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define DHT22_PIN 4
#define NUM_RETRIES 3
#define MAX_TIMEOUT_US 100000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint64_t now_us(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (uint64_t)ts.tv_sec * 1000000ULL + (uint64_t)ts.tv_nsec / 1000ULL;
}

static int wait_for_level(struct gpiod_line *line, int target, uint64_t timeout_us) {
    uint64_t deadline = now_us() + timeout_us;
    for (;;) {
        if (!running) return -1;
        int val = gpiod_line_get_value(line);
        if (val < 0) return -1;
        if (val == target) return 0;
        if (now_us() >= deadline) return -1;
    }
}

static int read_dht22(struct gpiod_line *line, float *temp, float *hum) {
    uint8_t data[5] = {0};
    int i;

    if (gpiod_line_request_output(line, "dht22", 1) < 0) return -1;
    usleep(1000);
    if (gpiod_line_set_value(line, 0) < 0) return -1;
    usleep(20000);
    if (gpiod_line_set_value(line, 1) < 0) return -1;
    usleep(30);
    if (gpiod_line_request_input(line, "dht22") < 0) return -1;

    if (wait_for_level(line, 0, MAX_TIMEOUT_US) < 0) return -1;
    if (wait_for_level(line, 1, MAX_TIMEOUT_US) < 0) return -1;
    if (wait_for_level(line, 0, MAX_TIMEOUT_US) < 0) return -1;

    for (i = 0; i < 40; i++) {
        if (wait_for_level(line, 1, MAX_TIMEOUT_US) < 0) return -1;
        uint64_t t0 = now_us();
        if (wait_for_level(line, 0, MAX_TIMEOUT_US) < 0) return -1;
        uint64_t elapsed = now_us() - t0;
        if (elapsed > 50) data[i / 8] |= (1 << (7 - (i % 8)));
    }

    uint8_t checksum = data[0] + data[1] + data[2] + data[3];
    if (checksum != data[4]) return -1;

    uint16_t raw_h = (data[0] << 8) | data[1];
    uint16_t raw_t = (data[2] << 8) | data[3];
    *hum = raw_h / 10.0f;
    if (raw_t & 0x8000) {
        *temp = -(raw_t & 0x7FFF) / 10.0f;
    } else {
        *temp = raw_t / 10.0f;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    float temp, hum;
    int rc = EXIT_FAILURE;

    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, DHT22_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    for (int cycle = 0; cycle < NUM_RETRIES && running; cycle++) {
        printf("Cycle %d/%d\n", cycle + 1, NUM_RETRIES);
        if (read_dht22(line, &temp, &hum) == 0) {
            printf("Temperature: %.1f C, Humidity: %.1f %%\n", temp, hum);
            rc = EXIT_SUCCESS;
        } else {
            fprintf(stderr, "Read failed\n");
        }
        if (running) sleep(2);
    }

cleanup:
    if (line) gpiod_line_release(line);
    if (chip) gpiod_chip_close(chip);
    return rc;
}

