#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PINS {4, 17, 18, 27}
#define NUM_PINS 4
#define CYCLE_SEC 60

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int pins[NUM_PINS] = PWM_PINS;
    int i;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    for (i = 0; i < NUM_PINS; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "gpioSetMode failed on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioPWM(pins[i], 0) != 0) {
            fprintf(stderr, "gpioPWM init failed on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    for (i = 0; i < 5 && running; i++) {
        printf("Cycle %d/%d: pins=%d,%d,%d,%d\n", i + 1, 5, pins[0], pins[1], pins[2], pins[3]);
        fflush(stdout);

        for (int j = 0; j < NUM_PINS; j++) {
            if (gpioPWM(pins[j], 128) != 0) {
                fprintf(stderr, "gpioPWM set failed on GPIO %d\n", pins[j]);
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }
        sleep(CYCLE_SEC);

        for (int j = 0; j < NUM_PINS; j++) {
            if (gpioPWM(pins[j], 0) != 0) {
                fprintf(stderr, "gpioPWM clear failed on GPIO %d\n", pins[j]);
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }
        sleep(CYCLE_SEC);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

