#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PINS {17, 18, 22, 23, 24, 25}
#define NUM_PINS 6
#define PWM_RANGE 255
#define PWM_FREQ 1000
#define STEP_DELAY_US 50000

static const int pwm_pins[NUM_PINS] = PWM_PINS;

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGTERM handler\n");
    }

    for (int i = 0; i < NUM_PINS; i++) {
        if (gpioSetMode(pwm_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output\n", pwm_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(pwm_pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Error: failed to set PWM range on GPIO %d\n", pwm_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(pwm_pins[i], PWM_FREQ) < 0) {
            fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d\n", pwm_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioPWM(pwm_pins[i], 0) != 0) {
            fprintf(stderr, "Error: failed to initialise PWM on GPIO %d\n", pwm_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    int duty = 0;
    int direction = 1;

    while (running) {
        for (int i = 0; i < NUM_PINS; i++) {
            if (gpioPWM(pwm_pins[i], duty) != 0) {
                fprintf(stderr, "Error: failed to set PWM on GPIO %d\n", pwm_pins[i]);
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }
        printf("PWM duty: %d\n", duty);
        fflush(stdout);

        duty += direction;
        if (duty >= PWM_RANGE) {
            duty = PWM_RANGE;
            direction = -1;
        } else if (duty <= 0) {
            duty = 0;
            direction = 1;
        }

        usleep(STEP_DELAY_US);
    }

    for (int i = 0; i < NUM_PINS; i++) {
        gpioPWM(pwm_pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

