#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define DHT22_PIN_1 4
#define DHT22_PIN_2 17
#define MAX_TIMINGS 85
#define DHT_TIMEOUT 255

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int wait_for_level(struct gpiod_line *line, int target, int timeout) {
    for (int i = 0; i < timeout; i++) {
        if (gpiod_line_get_value(line) == target) return i;
        usleep(1);
    }
    return -1;
}

static int read_dht22(struct gpiod_line *line, float *temp, float *hum) {
    uint8_t data[5] = {0, 0, 0, 0, 0};
    int laststate = 1;
    int bits = 0;

    if (gpiod_line_request_output(line, "dht22", 1) < 0) return -1;
    usleep(1000);
    gpiod_line_set_value(line, 0);
    usleep(20000);
    gpiod_line_set_value(line, 1);
    usleep(40);
    if (gpiod_line_request_input(line, "dht22") < 0) return -1;

    if (wait_for_level(line, 0, DHT_TIMEOUT) < 0) return -2;
    if (wait_for_level(line, 1, DHT_TIMEOUT) < 0) return -2;
    if (wait_for_level(line, 0, DHT_TIMEOUT) < 0) return -2;

    for (int i = 0; i < MAX_TIMINGS; i++) {
        int count = 0;
        while (gpiod_line_get_value(line) == laststate) {
            count++;
            usleep(1);
            if (count == DHT_TIMEOUT) return -3;
        }
        laststate = gpiod_line_get_value(line);

        if (count > 4) {
            data[bits / 8] <<= 1;
            if (count > 16) data[bits / 8] |= 1;
            bits++;
            if (bits > 40) break;
        }
    }

    if (bits < 40) return -4;
    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) return -5;

    uint16_t raw_h = (data[0] << 8) | data[1];
    uint16_t raw_t = (data[2] << 8) | data[3];
    *hum = (float)raw_h / 10.0f;
    *temp = (float)(raw_t & 0x7FFF) / 10.0f;
    if (raw_t & 0x8000) *temp = -*temp;
    return 0;
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    struct gpiod_line *line1 = gpiod_chip_get_line(chip, DHT22_PIN_1);
    struct gpiod_line *line2 = gpiod_chip_get_line(chip, DHT22_PIN_2);
    if (!line1 || !line2) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    for (int i = 0; i < 3 && running; i++) {
        float t1 = 0.0f, h1 = 0.0f;
        float t2 = 0.0f, h2 = 0.0f;
        int r1 = read_dht22(line1, &t1, &h1);
        int r2 = read_dht22(line2, &t2, &h2);

        if (r1 == 0) printf("GPIO %d: Temp=%.1fC, Hum=%.1f%%\n", DHT22_PIN_1, t1, h1);
        else printf("GPIO %d: Read failed (code %d)\n", DHT22_PIN_1, r1);
        if (r2 == 0) printf("GPIO %d: Temp=%.1fC, Hum=%.1f%%\n", DHT22_PIN_2, t2, h2);
        else printf("GPIO %d: Read failed (code %d)\n", DHT22_PIN_2, r2);

        for (int s = 0; s < 60 && running; s++) sleep(1);
    }

    gpiod_chip_close(chip);
    return 0;
}

