#define PWM_PIN_2 18
#define PWM_PIN_3 27

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN_1, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN_1);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN_2, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN_2);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN_3, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN_3);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int duty1 = 128;
        int duty2 = 255;
        int duty3 = 0;

        if (gpioPWM(PWM_PIN_1, duty1) != 0) {
            fprintf(stderr, "Failed to set PWM on GPIO %d\n", PWM_PIN_1);
            break;
        }
        if (gpioPWM(PWM_PIN_2, duty2) != 0) {
            fprintf(stderr, "Failed to set PWM on GPIO %d\n", PWM_PIN_2);
            break;
        }
        if (gpioPWM(PWM_PIN_3, duty3) != 0) {
            fprintf(stderr, "Failed to set PWM on GPIO %d\n", PWM_PIN_3);
            break;
        }

        printf("PWM on GPIO %d: %d, GPIO %d: %d, GPIO %d: %d\n",
               PWM_PIN_1, duty1, PWM_PIN_2, duty2, PWM_PIN_3, duty3);
        fflush(stdout);

        gpioDelay(1000000);
    }

    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

