#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 18
#define POLL_INTERVAL_SEC 2

static volatile sig_atomic_t running = 1;

static void sigint_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request the line as output, initial value LOW */
    if (gpiod_line_request_output(line, "blink", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    printf("Starting 2-second blink on GPIO %d. Press Ctrl+C to exit.\n", GPIO_LINE);

    while (running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }

        /* Toggle the output */
        val = !val;
        if (gpiod_line_set_value(line, val) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }

        printf("GPIO %d set to %d\n", GPIO_LINE, val);

        /* Sleep for 2 seconds, checking running flag every 100 ms */
        for (int i = 0; i < POLL_INTERVAL_SEC * 10 && running; i++) {
            usleep(100000); /* 100 ms */
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure the line is released even on error paths */
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting cleanly.\n");
    }
    return ret;
}

