#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define GPIO_CHIP "/dev/gpiochip0"

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa = {0};
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        perror("gpiod_line_request_output trig");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        perror("gpiod_line_request_input echo");
        goto cleanup;
    }

    /* Ensure trigger starts low */
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("gpiod_line_set_value low");
        goto cleanup;
    }
    usleep(50000); /* 50 ms settle */

    /* 10 us trigger pulse */
    if (gpiod_line_set_value(trig, 1) < 0) {
        perror("gpiod_line_set_value high");
        goto cleanup;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("gpiod_line_set_value low");
        goto cleanup;
    }

    /* Wait for echo rising edge (timeout 100 ms) */
    int val;
    int waited = 0;
    while ((val = gpiod_line_get_value(echo)) == 0) {
        if (!running) goto cleanup;
        usleep(100);
        waited += 100;
        if (waited >= 100000) {
            fprintf(stderr, "Timeout waiting for echo rising edge\n");
            goto cleanup;
        }
    }
    if (val < 0) {
        perror("gpiod_line_get_value");
        goto cleanup;
    }

    /* Measure echo high duration */
    struct timespec t_start, t_now;
    clock_gettime(CLOCK_MONOTONIC, &t_start);
    while ((val = gpiod_line_get_value(echo)) == 1) {
        if (!running) goto cleanup;
        clock_gettime(CLOCK_MONOTONIC, &t_now);
        long elapsed_us = (t_now.tv_sec - t_start.tv_sec) * 1000000L +
                          (t_now.tv_nsec - t_start.tv_nsec) / 1000L;
        if (elapsed_us > 300000) {
            fprintf(stderr, "Timeout waiting for echo falling edge\n");
            goto cleanup;
        }
        usleep(100);
    }
    if (val < 0) {
        perror("gpiod_line_get_value");
        goto cleanup;
    }

    clock_gettime(CLOCK_MONOTONIC, &t_now);
    long elapsed_us = (t_now.tv_sec - t_start.tv_sec) * 1000000L +
                      (t_now.tv_nsec - t_start.tv_nsec) / 1000L;
    float distance = (elapsed_us / 2.0f) * 0.0343f;
    printf("Distance: %.2f cm\n", distance);

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

