#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define VEML7700_ADDR 0x10
#define I2C_DEV "/dev/i2c-1"

#define VEML7700_REG_CONFIG 0x00
#define VEML7700_REG_ALS_DATA 0x04

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error selecting register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

int main(void) {
    int fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_DEV, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", VEML7700_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (i2c_write_reg8(fd, VEML7700_REG_CONFIG, 0x0000) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        uint16_t als_data = 0;
        if (i2c_read_reg16(fd, VEML7700_REG_ALS_DATA, &als_data) < 0) {
            close(fd);
            return EXIT_FAILURE;
        }
        printf("ALS Data: %u\n", als_data);
        fflush(stdout);
        sleep(1);
    }

    i2c_write_reg8(fd, VEML7700_REG_CONFIG, 0x0000);
    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <signal.h>

#define SERIAL_PORT "/dev/ttyAMA0"
#define BAUD_RATE B115200
#define READ_INTERVAL_US 100000
#define READ_TIMEOUT_MS 100

static volatile sig_atomic_t keep_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

static int init_serial(const char *port, speed_t baud) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        perror("Error opening serial port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    cfsetispeed(&tty, baud);
    cfsetospeed(&tty, baud);

    tty.c_cflag = CS8 | CLOCAL | CREAD;
    tty.c_iflag = IGNPAR;
    tty.c_oflag = 0;
    tty.c_lflag = 0;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = READ_TIMEOUT_MS / 100;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

static int read_serial(int fd, char *buffer, size_t buffer_size) {
    ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
    if (bytes_read < 0) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            return 0;
        }
        perror("Error reading from serial port");
        return -1;
    }
    if (bytes_read == 0) {
        return 0;
    }
    buffer[bytes_read] = '\0';
    return (int)bytes_read;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error setting SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error setting SIGTERM handler");
        return EXIT_FAILURE;
    }

    int fd = init_serial(SERIAL_PORT, BAUD_RATE);
    if (fd < 0) {
        return EXIT_FAILURE;
    }

    char buffer[256];
    while (keep_running) {
        int result = read_serial(fd, buffer, sizeof(buffer));
        if (result > 0) {
            printf("Received: %s", buffer);
            fflush(stdout);
        } else if (result < 0) {
            fprintf(stderr, "Error reading from serial port. Exiting.\n");
            break;
        }
        usleep(READ_INTERVAL_US);
    }

    if (close(fd) != 0) {
        perror("Error closing serial port");
    }
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define CONSUMER    "hcsr04"

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trig) {
        perror("gpiod_chip_get_line(trigger)");
        goto cleanup;
    }
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        perror("gpiod_chip_get_line(echo)");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(trigger)");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, CONSUMER) < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }

    while (running) {
        /* Ensure trigger is low for a clean pulse */
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value(trig low)");
            break;
        }
        usleep(2);

        /* 10-microsecond trigger pulse */
        if (gpiod_line_set_value(trig, 1) < 0) {
            perror("gpiod_line_set_value(trig high)");
            break;
        }
        usleep(10);
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value(trig low)");
            break;
        }

        /* Wait for echo rising edge (timeout 1 second) */
        int val;
        int elapsed = 0;
        while (elapsed < 1000000) {
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                perror("gpiod_line_get_value(echo)");
                goto cleanup;
            }
            if (val == 1) break;
            usleep(10);
            elapsed += 10;
        }
        if (val != 1) {
            fprintf(stderr, "Timeout waiting for echo rising edge\n");
            goto cleanup;
        }

        /* Measure echo high duration (timeout 1 second) */
        elapsed = 0;
        while (elapsed < 1000000) {
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                perror("gpiod_line_get_value(echo)");
                goto cleanup;
            }
            if (val == 0) break;
            usleep(10);
            elapsed += 10;
        }
        if (val != 0) {
            fprintf(stderr, "Timeout waiting for echo falling edge\n");
            goto cleanup;
        }

        double distance = (double)elapsed / 58.0;
        if (distance < 2.0 || distance > 400.0) {
            fprintf(stderr, "Out-of-range reading: %.2f cm\n", distance);
        } else {
            printf("Distance: %.2f cm\n", distance);
            fflush(stdout);
        }

        sleep(1);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return rc;
}

