#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_BW_RATE 0x2C
#define ADXL345_REG_DATA_FORMAT 0x31

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error selecting reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "Error reading reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error selecting reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "Error reading burst from 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ADXL345_ADDRESS, strerror(errno));
        goto cleanup;
    }

    if (i2c_write_reg8(fd, ADXL345_REG_POWER_CTL, 0x00) < 0) goto cleanup;
    if (i2c_write_reg8(fd, ADXL345_REG_BW_RATE, 0x0A) < 0) goto cleanup;
    if (i2c_write_reg8(fd, ADXL345_REG_DATA_FORMAT, 0x08) < 0) goto cleanup;
    if (i2c_write_reg8(fd, ADXL345_REG_POWER_CTL, 0x08) < 0) goto cleanup;

    while (running) {
        uint8_t data[6];
        if (i2c_read_burst(fd, ADXL345_REG_DATAX0, data, 6) < 0) {
            fprintf(stderr, "Failed to read acceleration data\n");
            goto cleanup;
        }

        int16_t x = (int16_t)((data[1] << 8) | data[0]);
        int16_t y = (int16_t)((data[3] << 8) | data[2]);
        int16_t z = (int16_t)((data[5] << 8) | data[4]);

        printf("X: %d, Y: %d, Z: %d\n", x, y, z);
        fflush(stdout);

        usleep(100000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        i2c_write_reg8(fd, ADXL345_REG_POWER_CTL, 0x00);
        close(fd);
    }
    return ret;
}

