static long measure_distance(struct gpiod_line *trig, struct gpiod_line *echo) {
    struct timespec ts_start, ts_now;
    long elapsed_ns, distance_cm;
    int val;

    /* Ensure trigger is low for a clean pulse */
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
        return -1;
    }
    usleep(2);

    /* 10us trigger pulse */
    if (gpiod_line_set_value(trig, 1) < 0) {
        fprintf(stderr, "Failed to set trigger high: %s\n", strerror(errno));
        return -1;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
        return -1;
    }

    /* Wait for echo rising edge (timeout 100ms) */
    clock_gettime(CLOCK_MONOTONIC, &ts_start);
    do {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            fprintf(stderr, "Failed to read echo: %s\n", strerror(errno));
            return -1;
        }
        if (val == 1) break;
        clock_gettime(CLOCK_MONOTONIC, &ts_now);
    } while ((ts_now.tv_sec - ts_start.tv_sec) * 1000 +
             (ts_now.tv_nsec - ts_start.tv_nsec) / 1000000 < 100);
    if (val != 1) {
        fprintf(stderr, "Timeout waiting for echo start\n");
        return -1;
    }

    /* Measure echo pulse width */
    clock_gettime(CLOCK_MONOTONIC, &ts_start);
    do {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            fprintf(stderr, "Failed to read echo: %s\n", strerror(errno));
            return -1;
        }
        if (val == 0) break;
        clock_gettime(CLOCK_MONOTONIC, &ts_now);
    } while ((ts_now.tv_sec - ts_start.tv_sec) * 1000 +
             (ts_now.tv_nsec - ts_start.tv_nsec) / 1000000 < 100000);
    if (val != 0) {
        fprintf(stderr, "Timeout waiting for echo end\n");
        return -1;
    }

    elapsed_ns = (ts_now.tv_sec - ts_start.tv_sec) * 1000000000L +
                 (ts_now.tv_nsec - ts_start.tv_nsec);
    distance_cm = (elapsed_ns / 1000) / 58;

    if (distance_cm < 2 || distance_cm > 400) {
        fprintf(stderr, "Distance out of range: %ld cm\n", distance_cm);
        return -1;
    }
    return distance_cm;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
