    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", TCS34725_ADDRESS, strerror(errno));
        close(fd);
        return 1;
    }

    uint8_t id;
    if (i2c_read_reg8(fd, TCS34725_COMMAND_BIT, &id) < 0) {
        fprintf(stderr, "TCS34725 not detected at address 0x%02X\n", TCS34725_ADDRESS);
        close(fd);
        return 1;
    }

    if (tcs34725_init(fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        close(fd);
        return 1;
    }

    while (running) {
        uint16_t clear, red, green, blue;
        if (tcs34725_read_data(fd, &clear, &red, &green, &blue) == 0) {
            printf("Clear: %u, Red: %u, Green: %u, Blue: %u\n", clear, red, green, blue);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }
        sleep(1);
    }

    i2c_write_reg8(fd, TCS34725_ENABLE, 0x00);
    close(fd);
    return 0;
}

