#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 2
#define PWM_PIN_2 3
#define PWM_PIN_3 18

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int rc;

    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "pigpio initialisation failed (code %d).\n", rc);
        fprintf(stderr, "Is the pigpio daemon running? Try: sudo pigpiod\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGINT handler.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGTERM handler.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN_1, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output.\n", PWM_PIN_1);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN_2, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output.\n", PWM_PIN_2);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN_3, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output.\n", PWM_PIN_3);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int duty = 128;
        if (gpioPWM(PWM_PIN_1, duty) != 0) {
            fprintf(stderr, "Failed to set PWM on GPIO %d.\n", PWM_PIN_1);
            break;
        }
        if (gpioPWM(PWM_PIN_2, duty) != 0) {
            fprintf(stderr, "Failed to set PWM on GPIO %d.\n", PWM_PIN_2);
            break;
        }
        if (gpioPWM(PWM_PIN_3, duty) != 0) {
            fprintf(stderr, "Failed to set PWM on GPIO %d.\n", PWM_PIN_3);
            break;
        }

        printf("PWM on GPIO %d, %d, %d set to %d/255.\n",
               PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, duty);
        fflush(stdout);

        sleep(5);
    }

    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

