#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 18
#define ECHO_PIN 23
#define LED_PIN 24

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL, *led = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    led = gpiod_chip_get_line(chip, LED_PIN);
    if (!trig || !echo || !led) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        perror("gpiod_line_request_output trig");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        perror("gpiod_line_request_input echo");
        goto cleanup;
    }
    if (gpiod_line_request_output(led, "hcsr04-led", 0) < 0) {
        perror("gpiod_line_request_output led");
        goto cleanup;
    }

    /* Ensure trigger starts low */
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("gpiod_line_set_value trig low");
        goto cleanup;
    }
    usleep(50000); /* 50 ms settle */

    /* 10 us trigger pulse */
    if (gpiod_line_set_value(trig, 1) < 0) {
        perror("gpiod_line_set_value trig high");
        goto cleanup;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("gpiod_line_set_value trig low");
        goto cleanup;
    }

    /* Wait for echo rising edge (timeout 100 ms) */
    int val;
    for (int i = 0; i < 100; i++) {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            perror("gpiod_line_get_value echo");
            goto cleanup;
        }
        if (val == 1) break;
        usleep(1000);
    }
    if (val != 1) {
        fprintf(stderr, "HC-SR04 not responding (echo stuck low)\n");
        goto cleanup;
    }

    /* Measure echo pulse width */
    struct timespec t_start, t_now;
    clock_gettime(CLOCK_MONOTONIC, &t_start);

    for (int i = 0; i < 100; i++) {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            perror("gpiod_line_get_value echo");
            goto cleanup;
        }
        if (val == 0) break;
        usleep(1000);
    }
    if (val != 0) {
        fprintf(stderr, "HC-SR04 echo stuck high (timeout)\n");
        goto cleanup;
    }

    clock_gettime(CLOCK_MONOTONIC, &t_now);
    long long elapsed_ns = (t_now.tv_sec - t_start.tv_sec) * 1000000000LL +
                           (t_now.tv_nsec - t_start.tv_nsec);
    double distance = (double)elapsed_ns / 58.0 / 1000.0; /* cm */

    printf("Distance: %.2f cm\n", distance);

    if (distance < 200.0) {
        if (gpiod_line_set_value(led, 1) < 0) {
            perror("gpiod_line_set_value led on");
            goto cleanup;
        }
        printf("Object detected within 200 cm - LED ON\n");
    } else {
        if (gpiod_line_set_value(led, 0) < 0) {
            perror("gpiod_line_set_value led off");
            goto cleanup;
        }
        printf("Object not within 200 cm - LED OFF\n");
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (led) gpiod_line_release(led);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

